CREATE TABLE IF NOT EXISTS settings (name VARCHAR(64) PRIMARY KEY,revision INT NOT NULL DEFAULT 1,value JSON NOT NULL);
CREATE TABLE IF NOT EXISTS configuration_revisions (id BIGINT PRIMARY KEY AUTO_INCREMENT,resource_kind VARCHAR(64) NOT NULL,resource_id BIGINT NOT NULL,revision INT NOT NULL,snapshot JSON NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY configuration_revision(resource_kind,resource_id,revision));
CREATE TABLE IF NOT EXISTS preferences (id BIGINT PRIMARY KEY AUTO_INCREMENT,scope VARCHAR(20) NOT NULL,scope_id BIGINT NOT NULL,revision INT NOT NULL DEFAULT 1,value JSON NOT NULL,UNIQUE KEY preference_scope(scope,scope_id));
CREATE TABLE IF NOT EXISTS cleanup_runs (id BIGINT PRIMARY KEY AUTO_INCREMENT,summary JSON NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS directories (id BIGINT PRIMARY KEY AUTO_INCREMENT,kind VARCHAR(32) NOT NULL,name VARCHAR(160) NOT NULL,revision INT NOT NULL DEFAULT 1,enabled BOOLEAN NOT NULL DEFAULT TRUE,config JSON NOT NULL,UNIQUE KEY directory_identity(kind,name));
CREATE TABLE IF NOT EXISTS assets (id BIGINT PRIMARY KEY AUTO_INCREMENT,sha256 CHAR(64) NOT NULL UNIQUE,name VARCHAR(240) NOT NULL,mime VARCHAR(100) NOT NULL,extension VARCHAR(12) NOT NULL,byte_size BIGINT NOT NULL,width INT,height INT,kind VARCHAR(24) NOT NULL DEFAULT 'original',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS products (id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(240) NOT NULL,category_id BIGINT NOT NULL,origin VARCHAR(20) NOT NULL,revision INT NOT NULL DEFAULT 1,description JSON NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY product_page(category_id,id),FOREIGN KEY(category_id) REFERENCES directories(id));
CREATE TABLE IF NOT EXISTS skus (id BIGINT PRIMARY KEY AUTO_INCREMENT,product_id BIGINT NOT NULL,code VARCHAR(120) COLLATE utf8mb4_bin NOT NULL UNIQUE,label VARCHAR(240) NOT NULL,revision INT NOT NULL DEFAULT 1,facts JSON NOT NULL,components JSON NOT NULL,original_asset_id BIGINT,provenance JSON NOT NULL,supplier_id BIGINT,supplier_code VARCHAR(160) COLLATE utf8mb4_bin,UNIQUE KEY supplier_sku(supplier_id,supplier_code),KEY sku_product(product_id,id),FOREIGN KEY(product_id) REFERENCES products(id),FOREIGN KEY(original_asset_id) REFERENCES assets(id));
CREATE TABLE IF NOT EXISTS jobs (id BIGINT PRIMARY KEY AUTO_INCREMENT,kind VARCHAR(32) NOT NULL,entity_id BIGINT,intent_key VARCHAR(160) NOT NULL UNIQUE,status VARCHAR(20) NOT NULL DEFAULT 'queued',stage VARCHAR(160) NOT NULL DEFAULT '等待开始',progress INT NOT NULL DEFAULT 0,payload JSON NOT NULL,steps JSON NOT NULL,result JSON,error TEXT,cancel_requested BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY job_queue(status,id));
CREATE TABLE IF NOT EXISTS sources (id BIGINT PRIMARY KEY AUTO_INCREMENT,kind VARCHAR(20) NOT NULL,platform VARCHAR(100) NOT NULL,url VARCHAR(2000) NOT NULL,title VARCHAR(500) NOT NULL,excerpt TEXT NOT NULL,source_category VARCHAR(160) NOT NULL DEFAULT '',observed_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,product_id BIGINT,elements JSON NOT NULL,revision INT NOT NULL DEFAULT 1,job_id BIGINT,identity_key CHAR(64) UNIQUE,fingerprint CHAR(64) UNIQUE,meta JSON,KEY source_page(kind,product_id,id),FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE IF NOT EXISTS product_sources (product_id BIGINT NOT NULL,source_id BIGINT NOT NULL,elements JSON NOT NULL,PRIMARY KEY(product_id,source_id),FOREIGN KEY(product_id) REFERENCES products(id),FOREIGN KEY(source_id) REFERENCES sources(id));
CREATE TABLE IF NOT EXISTS source_adoptions (id BIGINT PRIMARY KEY AUTO_INCREMENT,source_id BIGINT NOT NULL,product_id BIGINT NOT NULL,elements JSON NOT NULL,snapshot JSON NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY source_adoption(source_id,product_id),FOREIGN KEY(source_id) REFERENCES sources(id),FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE IF NOT EXISTS designs (id BIGINT PRIMARY KEY AUTO_INCREMENT,product_id BIGINT NOT NULL,sku_id BIGINT NOT NULL,mode VARCHAR(20) NOT NULL,brief TEXT NOT NULL,source_ids JSON NOT NULL,config JSON NOT NULL,revision INT NOT NULL DEFAULT 1,status VARCHAR(20) NOT NULL DEFAULT 'draft',job_id BIGINT,input_revision JSON NOT NULL,input_snapshot JSON NOT NULL,parent_id BIGINT,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY design_product(product_id,id),FOREIGN KEY(product_id) REFERENCES products(id),FOREIGN KEY(sku_id) REFERENCES skus(id));
CREATE TABLE IF NOT EXISTS design_assets (id BIGINT PRIMARY KEY AUTO_INCREMENT,design_id BIGINT NOT NULL,asset_id BIGINT NOT NULL,role VARCHAR(64) NOT NULL,label VARCHAR(240) NOT NULL,version INT NOT NULL DEFAULT 1,parent_asset_id BIGINT,meta JSON NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY design_role(design_id,role,version),FOREIGN KEY(design_id) REFERENCES designs(id),FOREIGN KEY(asset_id) REFERENCES assets(id));
CREATE TABLE IF NOT EXISTS targets (id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(160) NOT NULL,platform VARCHAR(32) NOT NULL,site VARCHAR(80) NOT NULL,mode VARCHAR(100) NOT NULL,category VARCHAR(160) NOT NULL,language VARCHAR(40) NOT NULL,currency CHAR(3) NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE,revision INT NOT NULL DEFAULT 1,UNIQUE KEY target_identity(name,platform,site,mode,category));
CREATE TABLE IF NOT EXISTS listings (id BIGINT PRIMARY KEY AUTO_INCREMENT,product_id BIGINT NOT NULL,sku_id BIGINT NOT NULL,target_id BIGINT NOT NULL,design_id BIGINT,revision INT NOT NULL DEFAULT 1,fields JSON NOT NULL,images JSON NOT NULL,status VARCHAR(24) NOT NULL DEFAULT 'draft',input_revision JSON NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY listing_sku(sku_id,target_id),KEY listing_product(product_id,id),FOREIGN KEY(product_id) REFERENCES products(id),FOREIGN KEY(sku_id) REFERENCES skus(id),FOREIGN KEY(target_id) REFERENCES targets(id),FOREIGN KEY(design_id) REFERENCES designs(id));
CREATE TABLE IF NOT EXISTS imports (id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(240) NOT NULL,supplier_id BIGINT NOT NULL,source_asset_id BIGINT NOT NULL,revision INT NOT NULL DEFAULT 1,status VARCHAR(24) NOT NULL DEFAULT 'parsed',config JSON,mapping JSON NOT NULL,summary JSON NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(source_asset_id) REFERENCES assets(id));
CREATE TABLE IF NOT EXISTS import_rows (id BIGINT PRIMARY KEY AUTO_INCREMENT,import_id BIGINT NOT NULL,row_no INT NOT NULL,sheet_name VARCHAR(160) NOT NULL DEFAULT '',raw JSON NOT NULL,images JSON NOT NULL,issues JSON NOT NULL,status VARCHAR(24) NOT NULL DEFAULT 'pending',product_id BIGINT,sku_id BIGINT,UNIQUE KEY import_row(import_id,sheet_name,row_no),FOREIGN KEY(import_id) REFERENCES imports(id));
CREATE TABLE IF NOT EXISTS templates (id BIGINT PRIMARY KEY AUTO_INCREMENT,target_id BIGINT NOT NULL,name VARCHAR(240) NOT NULL,asset_id BIGINT NOT NULL,revision INT NOT NULL DEFAULT 1,config JSON NOT NULL,capability VARCHAR(32) NOT NULL DEFAULT 'registered',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(target_id) REFERENCES targets(id),FOREIGN KEY(asset_id) REFERENCES assets(id));
CREATE TABLE IF NOT EXISTS exports (id BIGINT PRIMARY KEY AUTO_INCREMENT,target_id BIGINT NOT NULL,template_id BIGINT NOT NULL,asset_id BIGINT,status VARCHAR(32) NOT NULL DEFAULT 'exported',intent_key VARCHAR(160) UNIQUE,fingerprint CHAR(64) UNIQUE,snapshot JSON NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(target_id) REFERENCES targets(id),FOREIGN KEY(template_id) REFERENCES templates(id),FOREIGN KEY(asset_id) REFERENCES assets(id));
CREATE TABLE IF NOT EXISTS receipts (id BIGINT PRIMARY KEY AUTO_INCREMENT,export_id BIGINT NOT NULL,asset_id BIGINT NOT NULL,batch_reference VARCHAR(240) NOT NULL DEFAULT '',status VARCHAR(32) NOT NULL DEFAULT 'unverified',parsed JSON NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(export_id) REFERENCES exports(id),FOREIGN KEY(asset_id) REFERENCES assets(id));
CREATE TABLE IF NOT EXISTS production_outputs (id BIGINT PRIMARY KEY AUTO_INCREMENT,design_id BIGINT NOT NULL,asset_id BIGINT NOT NULL,source_asset_id BIGINT,fingerprint CHAR(64) UNIQUE,config JSON NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(design_id) REFERENCES designs(id),FOREIGN KEY(asset_id) REFERENCES assets(id));
CREATE TABLE IF NOT EXISTS listing_families (id BIGINT PRIMARY KEY AUTO_INCREMENT,target_id BIGINT NOT NULL,template_id BIGINT NOT NULL,parent_sku VARCHAR(120) COLLATE utf8mb4_bin NOT NULL,product_type VARCHAR(100) NOT NULL,variation VARCHAR(240) NOT NULL,listing_action VARCHAR(100) NOT NULL,revision INT NOT NULL DEFAULT 1,fields JSON NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY target_parent(target_id,parent_sku),KEY family_target(target_id,id),FOREIGN KEY(target_id) REFERENCES targets(id),FOREIGN KEY(template_id) REFERENCES templates(id));
CREATE TABLE IF NOT EXISTS family_members (family_id BIGINT NOT NULL,listing_id BIGINT NOT NULL,sort_order INT NOT NULL DEFAULT 0,PRIMARY KEY(family_id,listing_id),UNIQUE KEY one_listing_family(listing_id),FOREIGN KEY(family_id) REFERENCES listing_families(id),FOREIGN KEY(listing_id) REFERENCES listings(id));
CREATE TABLE IF NOT EXISTS public_image_assets (id BIGINT PRIMARY KEY AUTO_INCREMENT,asset_id BIGINT NOT NULL UNIQUE,sha256 CHAR(64) NOT NULL UNIQUE,extension VARCHAR(8) NOT NULL,mime VARCHAR(80) NOT NULL,byte_size BIGINT NOT NULL,status VARCHAR(24) NOT NULL DEFAULT 'registered',revision INT NOT NULL DEFAULT 1,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(asset_id) REFERENCES assets(id));
CREATE TABLE IF NOT EXISTS public_image_events (id BIGINT PRIMARY KEY AUTO_INCREMENT,publication_id BIGINT NOT NULL,action VARCHAR(24) NOT NULL,listing_id BIGINT,template_id BIGINT,fingerprint CHAR(64) NOT NULL UNIQUE,snapshot JSON NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY public_image_history(publication_id,id),FOREIGN KEY(publication_id) REFERENCES public_image_assets(id),FOREIGN KEY(listing_id) REFERENCES listings(id),FOREIGN KEY(template_id) REFERENCES templates(id));


